# Visual state helpers after badge
anchor="function badge(s){const c=s==='REEMBOLSADA'||s==='PAGO'?'green':['RECUSADA','CANCELADA','CANCELADO'].includes(s)?'red':['ENVIADA_PARA_APROVACAO','EM_ANALISE','AJUSTE_SOLICITADO','AGUARDANDO_REEMBOLSO','PARCIALMENTE_REEMBOLSADA','PARCIAL','PREVISTO'].includes(s)?'amber':'';return `<span class=\"badge ${c}\">${esc(labels[s]||s)}</span>`}"
if anchor not in js: raise SystemExit('badge anchor not found')
extra=anchor+"\n"+r'''function modificationBadge(x){const s=String(x?.modification_state||'NONE');if(s==='EDIT_REQUESTED')return '<span class="badge edit-requested">Edição solicitada</span>';if(s==='EDIT_GRANTED')return '<span class="badge edit-granted">Edição liberada</span>';if(s==='DELETE_REQUESTED')return '<span class="badge delete-requested">Exclusão solicitada</span>';return''}
function expenseVisualClass(x){const m=String(x?.modification_state||'NONE');if(m==='EDIT_REQUESTED')return'expense-edit-requested';if(m==='EDIT_GRANTED')return'expense-edit-granted';if(m==='DELETE_REQUESTED')return'expense-delete-requested';if(x.status==='AJUSTE_SOLICITADO')return'expense-edit-granted';if(['ENVIADA_PARA_APROVACAO','EM_ANALISE'].includes(x.status))return'expense-awaiting';if(['APROVADA','AGUARDANDO_REEMBOLSO','PARCIALMENTE_REEMBOLSADA','REEMBOLSADA'].includes(x.status))return'expense-approved';if(x.status==='RECUSADA')return'expense-rejected';return'expense-neutral'}
function expenseBadges(x){return badge(x.status)+(modificationBadge(x)?' '+modificationBadge(x):'')}
function canModifyFinancially(x){return Number(x?.reimbursed_amount||0)===0&&!['PARCIALMENTE_REEMBOLSADA','REEMBOLSADA','CANCELADA'].includes(x?.status)}'''
