# New-expense button must always reset edit state.
old="$('nav').onclick=e=>{const b=e.target.closest('button[data-v]');if(b)showView(b.dataset.v)};$('refresh').onclick=reload;$('globalCompany').onchange=reload;$('homeNew').onclick=$('expenseNew').onclick=()=>showView('new');"
new="$('nav').onclick=e=>{const b=e.target.closest('button[data-v]');if(b)showView(b.dataset.v)};$('refresh').onclick=reload;$('globalCompany').onchange=reload;$('homeNew').onclick=$('expenseNew').onclick=()=>{if(editingExpenseId)clearForm();showView('new')};"
if old not in js: raise SystemExit('new expense binding anchor not found')
js=js.replace(old,new,1)

# HTML visual colors + v18
css_anchor=".badge.amber{background:#fff2d7;color:#8d5700}"
css_extra=css_anchor+".badge.edit-requested{background:#fff4bf;color:#725600}.badge.edit-granted{background:#dff1ff;color:#15527a}.badge.delete-requested{background:#ffe4e6;color:#9f1239}.table tbody tr.expense-awaiting td,.rowcard.expense-awaiting{background:#fff3e8}.table tbody tr.expense-approved td,.rowcard.expense-approved{background:#eaf8ef}.table tbody tr.expense-edit-requested td,.rowcard.expense-edit-requested{background:#fff9d8}.table tbody tr.expense-edit-granted td,.rowcard.expense-edit-granted{background:#e8f5ff}.table tbody tr.expense-rejected td,.rowcard.expense-rejected{background:#fff0f0}.table tbody tr.expense-delete-requested td,.rowcard.expense-delete-requested{background:#fff1f2}.table tbody tr.expense-neutral td,.rowcard.expense-neutral{background:#fff}.table tbody tr.expense-awaiting:hover td,.rowcard.expense-awaiting:hover{background:#ffead6}.table tbody tr.expense-approved:hover td,.rowcard.expense-approved:hover{background:#dcf3e5}.table tbody tr.expense-edit-requested:hover td,.rowcard.expense-edit-requested:hover{background:#fff2bd}.table tbody tr.expense-edit-granted:hover td,.rowcard.expense-edit-granted:hover{background:#d9eeff}.table tbody tr.expense-rejected:hover td,.rowcard.expense-rejected:hover{background:#ffe1e1}.table tbody tr.expense-delete-requested:hover td,.rowcard.expense-delete-requested:hover{background:#ffe4e6}"
if css_anchor not in html: raise SystemExit('CSS anchor not found')
html=html.replace(css_anchor,css_extra,1)
html=re.sub(r'\.\/despesas-reembolsos-v2\.js\?v=\d+', './despesas-reembolsos-v2.js?v=18', html)

js_path.write_text(js,encoding='utf-8')
html_path.write_text(html,encoding='utf-8')
print('Expense edit/delete workflow and stage colors applied')
